#!/usr/bin/env python3
"""بيكتب أيقونات التطبيق الباني (SiMo Html to Apk) في res/mipmap-*. الاستخدام: builder_icons.py <res-dir>"""
import base64, os, sys
ICONS = {
 "mdpi": "",
 "hdpi": "",
 "xhdpi": "",
 "xxhdpi": "",
 "xxxhdpi": ""
}
res = sys.argv[1]
for d, b in ICONS.items():
    p = os.path.join(res, 'mipmap-' + d)
    os.makedirs(p, exist_ok=True)
    open(os.path.join(p, 'ic_launcher.png'), 'wb').write(base64.b64decode(b))
print('builder icons ok')
